function Dashboard({ items }) {
  const [selectedId, setSelectedId] = useState(null);
  const selectedItem = items.find((item) => item.id === selectedId);

  return (
    <>
      <ItemList items={items} selectedId={selectedId} onSelect={setSelectedId} />
      {selectedItem && <ItemDetails item={selectedItem} />}
    </>
  );
}

function ItemRow({ item, isSelected, onSelect }) {
  return (
    <button onClick={() => onSelect(item.id)}>
      {isSelected ? "Selected" : item.name}
    </button>
  );
}

function Progress({ tasks }) {
  const completed = tasks.filter((task) => task.done).length;
  const percent = tasks.length === 0 ? 0 : Math.round((completed / tasks.length) * 100);

  return <p>{percent}% complete</p>;
}

function FriendPanel({ friends, selectedId }) {
  const selectedFriend = friends.find((friend) => friend.id === selectedId);

  return selectedFriend ? <h2>{selectedFriend.name}</h2> : <p>No friend selected</p>;
}

const [isLoading, setIsLoading] = useState(false);

async function loadMovies() {
  try {
    setIsLoading(true);
    await fetchMovies();
  } finally {
    setIsLoading(false);
  }
}

return isLoading ? <p>Loading...</p> : <MovieList />;

const [error, setError] = useState("");

async function loadMovies() {
  try {
    setError("");
    await fetchMovies();
  } catch (error) {
    setError(error.message || "Something went wrong");
  }
}

return error ? <p role="alert">{error}</p> : <MovieList />;
